/** Bundled Tesseract `vie` engine (src/ocr-tesseract.ts + ocr-tesseract/tess-ocr.cjs)
 * on small committed scans (tests/fixtures/ocr, regenerated by gen_fixtures.py),
 * the protocol it speaks, the missing-asset contract, the shared resolver, and the
 * chain with a fake system engine. The helper is the real thing: tesseract.js WASM
 * + the committed tessdata_fast model, run as a child process like in the app. */
import { spawnSync } from 'node:child_process'
import {
  copyFileSync,
  existsSync,
  mkdirSync,
  mkdtempSync,
  readFileSync,
  realpathSync,
  rmSync,
  writeFileSync,
} from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { parseDocx } from '@genoffice/docx-engine'
import { PNG } from 'pngjs'
import { afterAll, beforeAll, describe, expect, it, vi } from 'vitest'
import { convertPdfToDocx } from '../src'
import type { ExtractedPage } from '../src/extract'
import { tryOcrScannedPage, type OcrEngine, type OcrLine, type OcrRecognition } from '../src/ocr'
import { chainOcrEngines, chainOcrEnginesAsync, ocrFallbackReason } from '../src/ocr-chain'
import { resolveLocalOcrEngine } from '../src/ocr-local'
import { createTesseractOcrEngine, createTesseractOcrEngineAsync } from '../src/ocr-tesseract'
import { loadPdfium } from './helpers/wasm'

// each helper run is a child process starting WASM: 1-5 s, more on a loaded CI box
vi.setConfig({ testTimeout: 60_000 })

const PKG = fileURLToPath(new URL('..', import.meta.url))
const HELPER = join(PKG, 'ocr-tesseract', 'tess-ocr.cjs')
const TESSDATA = join(PKG, 'ocr-tesseract', 'tessdata')
const FIXTURES = join(PKG, 'tests', 'fixtures', 'ocr')
const PAGE = { widthPt: 612, heightPt: 792 }

const png = (name: string) => new Uint8Array(readFileSync(join(FIXTURES, `${name}.png`)))
const groundTruth = (name: string) => readFileSync(join(FIXTURES, `${name}.gt.txt`), 'utf8')

const norm = (s: string) => s.normalize('NFC').replace(/\s+/g, ' ').trim()
function levenshtein(a: string[], b: string[]): number {
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i)
  for (let i = 1; i <= a.length; i++) {
    const cur = [i]
    for (let j = 1; j <= b.length; j++) {
      cur[j] = Math.min(
        prev[j]! + 1,
        cur[j - 1]! + 1,
        prev[j - 1]! + (a[i - 1] === b[j - 1] ? 0 : 1),
      )
    }
    prev = cur
  }
  return prev[b.length]!
}
const cer = (pred: string, gt: string) =>
  levenshtein([...norm(pred)], [...norm(gt)]) / [...norm(gt)].length

/** engine lines regrouped into reading order (y is bottom-left: top lines have the larger y) */
function readingOrder(lines: OcrLine[]): string {
  const rows: { y0: number; y1: number; items: OcrLine[] }[] = []
  for (const l of [...lines].sort((a, b) => b.box.y1 - a.box.y1)) {
    const h = l.box.y1 - l.box.y0
    const row = rows.find(
      (r) => Math.min(r.y1, l.box.y1) - Math.max(r.y0, l.box.y0) > 0.5 * Math.min(h, r.y1 - r.y0),
    )
    if (row) {
      row.items.push(l)
      row.y0 = Math.min(row.y0, l.box.y0)
      row.y1 = Math.max(row.y1, l.box.y1)
    } else rows.push({ y0: l.box.y0, y1: l.box.y1, items: [l] })
  }
  return rows
    .map((r) =>
      r.items
        .sort((a, b) => a.box.x0 - b.box.x0)
        .map((l) => l.text.trim())
        .join(' '),
    )
    .join('\n')
}

const recognitions: Record<string, OcrRecognition> = {}
let engine: OcrEngine

beforeAll(() => {
  const made = createTesseractOcrEngine({
    nodePath: process.execPath,
    helperScript: HELPER,
    tessdataDir: TESSDATA,
  })
  if (!made) throw new Error('bundled Tesseract engine unavailable (npm ci / tessdata missing?)')
  engine = made
  // one real helper run per page, shared by the tests below
  for (const name of ['vi', 'en', 'fr', 'zh', 'form']) {
    const result = engine(png(name), PAGE)
    if (!result) throw new Error(`tess-ocr returned no result for ${name}.png`)
    recognitions[name] = result
  }
}, 120_000)

const text = (name: string) => recognitions[name]!.lines.map((l) => l.text).join('\n')

describe('tess-ocr helper on scans', () => {
  it('reads a Vietnamese scan under 3% CER with its tone marks', () => {
    const got = readingOrder(recognitions.vi!.lines)
    expect(cer(got, groundTruth('vi'))).toBeLessThan(0.03)
    // every tone / vowel-mark family the text uses survives
    for (const ch of ['ộ', 'ữ', 'ầ', 'ặ', 'ỹ', 'ơ', 'ư', 'đ', 'ắ', 'ế']) {
      expect(got, `missing ${ch}`).toContain(ch)
    }
  })

  it('reads an English page under 2% CER', () => {
    expect(cer(readingOrder(recognitions.en!.lines), groundTruth('en'))).toBeLessThan(0.02)
  })

  it('reads a French page under 3% CER and keeps its accents', () => {
    const got = readingOrder(recognitions.fr!.lines)
    expect(cer(got, groundTruth('fr'))).toBeLessThan(0.03)
    // é è à ù are in the vie model; ç is not (it reads c) and is counted in the CER above
    for (const ch of ['é', 'è', 'à', 'ù']) expect(got, `missing ${ch}`).toContain(ch)
  })

  it('returns low confidence and foreign junk for a Chinese page (nothing to read honestly)', () => {
    const zh = recognitions.zh!
    expect(ocrFallbackReason(zh)).not.toBeNull()
    const chars = zh.lines.reduce((a, l) => a + [...l.text.replace(/\s/g, '')].length, 0)
    const mean =
      zh.lines.reduce((a, l) => a + l.confidence * [...l.text.replace(/\s/g, '')].length, 0) / chars
    expect(mean).toBeLessThan(0.6)
  })

  it('NFC-normalizes the text', () => {
    for (const name of ['vi', 'fr']) expect(text(name)).toBe(text(name).normalize('NFC'))
  })
})

describe('a Vietnamese form (underscore fill-in lines, ₫, bullets, @, | rows)', () => {
  const form = () => recognitions.form!

  it('is not mistaken for another script: no hand-over, Tesseract keeps the page', () => {
    expect(ocrFallbackReason(form())).toBeNull()
    const fallback = vi.fn<OcrEngine>(() => null)
    expect(chainOcrEngines(() => form(), fallback)(png('form'), PAGE)).toBe(form())
    expect(fallback).not.toHaveBeenCalled()
  })

  it('reads the words, numbers and ruled rows under 7% CER over what the model can emit', () => {
    // vie has no underscore, bullet or dong sign (measured: fill-in runs are not emitted at
    // all, • reads as » or «, ₫ as đ or 4), so those glyphs are scored out of both sides;
    // the rest is the form's text. Raw CER on this page is ~25% for that reason alone.
    const symbols = (t: string) => t.replace(/[_•₫|]+/g, ' ')
    const got = readingOrder(form().lines)
    expect(cer(symbols(got), symbols(groundTruth('form')))).toBeLessThan(0.07)
    for (const phrase of [
      'Họ và tên',
      'Ngày sinh',
      'Điện thoại',
      'Phòng ban',
      'Mua máy chủ dự phòng',
      '45.000.000',
      '12.500.000',
      '57.500.000',
      'Tổng cộng',
      'Người đề nghị ký tên',
      'Nội dung',
      'congty.vn',
    ]) {
      expect(got, phrase).toContain(phrase)
    }
  })
})

describe('tess-ocr protocol', () => {
  it('speaks the win-ocr / vision-ocr protocol: normalized bottom-left boxes, paper share', () => {
    const vi = recognitions.vi!
    expect(vi.paperShare).toBeGreaterThan(0.8)
    expect(vi.paperShare).toBeLessThanOrEqual(1)
    const first = vi.lines.find((l) => l.text.startsWith('Cộng hòa'))!
    const last = vi.lines.find((l) => l.text.startsWith('Ghi chú'))!
    expect(first).toBeDefined()
    expect(last).toBeDefined()
    // origin bottom-left, y up: the page's first line is near 1, its last line lower
    expect(first.box.y1).toBeGreaterThan(last.box.y1)
    expect(first.box.y1).toBeGreaterThan(0.8)
    expect(last.box.y0).toBeLessThan(0.3)
    for (const l of vi.lines) {
      expect(l.confidence).toBeGreaterThanOrEqual(0)
      expect(l.confidence).toBeLessThanOrEqual(1)
      expect(l.box.x0).toBeGreaterThanOrEqual(0)
      expect(l.box.x1).toBeLessThanOrEqual(1)
      expect(l.box.y0).toBeGreaterThanOrEqual(0)
      expect(l.box.y1).toBeLessThanOrEqual(1)
      expect(l.box.x1).toBeGreaterThan(l.box.x0)
      expect(l.box.y1).toBeGreaterThan(l.box.y0)
    }
  })

  it('returns one char entry per code point, glyph boxes inside the line box, zero boxes for spaces', () => {
    for (const l of recognitions.vi!.lines) {
      expect(l.chars, l.text).toBeDefined()
      expect(l.chars!.map((c) => c.text).join('')).toBe(l.text)
      expect(l.chars!.length).toBe([...l.text].length)
      const tol = 0.004
      for (const c of l.chars!) {
        if (c.text.trim() === '') {
          expect(c.box).toEqual({ x0: 0, y0: 0, x1: 0, y1: 0 })
          continue
        }
        expect(c.box.x1).toBeGreaterThan(c.box.x0)
        expect(c.box.x0).toBeGreaterThanOrEqual(l.box.x0 - tol)
        expect(c.box.x1).toBeLessThanOrEqual(l.box.x1 + tol)
        expect(c.box.y0).toBeGreaterThanOrEqual(l.box.y0 - tol)
        expect(c.box.y1).toBeLessThanOrEqual(l.box.y1 + tol)
      }
    }
  })

  it('keeps every normalized box inside [0, 1] when text touches the page edge', () => {
    // crop the page to its text extents so lines and glyphs run into all four edges
    const src = PNG.sync.read(Buffer.from(png('vi')))
    const margin = 80
    const w = src.width - 2 * margin + 8
    const h = src.height - 2 * margin + 8
    const crop = new PNG({ width: w, height: h })
    PNG.bitblt(src, crop, margin - 4, margin - 4, w, h, 0, 0)
    const got = engine(new Uint8Array(PNG.sync.write(crop)), PAGE)
    expect(got).not.toBeNull()
    const boxes = got!.lines.flatMap((l) => [l.box, ...(l.chars ?? []).map((c) => c.box)])
    expect(boxes.length).toBeGreaterThan(100)
    for (const b of boxes) {
      for (const v of [b.x0, b.y0, b.x1, b.y1]) {
        expect(v).toBeGreaterThanOrEqual(0)
        expect(v).toBeLessThanOrEqual(1)
      }
    }
    // the crop really is edge to edge: some glyph starts within 1% of the left edge
    expect(Math.min(...got!.lines.map((l) => l.box.x0))).toBeLessThan(0.02)
  })

  it('exits non-zero on undecodable input (the wrapper maps it to null)', () => {
    expect(engine(new Uint8Array([1, 2, 3, 4]), PAGE)).toBeNull()
    expect(engine(new Uint8Array(0), PAGE)).toBeNull()
  })
})

describe('missing assets', () => {
  it('returns null without the helper script', () => {
    expect(
      createTesseractOcrEngine({
        nodePath: process.execPath,
        helperScript: join(PKG, 'ocr-tesseract', 'no-such-helper.cjs'),
        tessdataDir: TESSDATA,
      }),
    ).toBeNull()
  })

  it('returns null without the language model', () => {
    const empty = mkdtempSync(join(tmpdir(), 'tess-empty-'))
    try {
      expect(
        createTesseractOcrEngine({
          nodePath: process.execPath,
          helperScript: HELPER,
          tessdataDir: empty,
        }),
      ).toBeNull()
      expect(
        createTesseractOcrEngine({
          nodePath: process.execPath,
          helperScript: HELPER,
          tessdataDir: TESSDATA,
          lang: 'vie+eng',
        }),
      ).toBeNull()
    } finally {
      rmSync(empty, { recursive: true, force: true })
    }
  })

  it('returns null when tesseract.js is not resolvable from the helper', () => {
    const lone = mkdtempSync(join(tmpdir(), 'tess-lone-'))
    try {
      copyFileSync(HELPER, join(lone, 'tess-ocr.cjs'))
      mkdirSync(join(lone, 'tessdata'))
      copyFileSync(join(TESSDATA, 'vie.traineddata'), join(lone, 'tessdata', 'vie.traineddata'))
      expect(
        createTesseractOcrEngine({
          nodePath: process.execPath,
          helperScript: join(lone, 'tess-ocr.cjs'),
          tessdataDir: join(lone, 'tessdata'),
        }),
      ).toBeNull()
    } finally {
      rmSync(lone, { recursive: true, force: true })
    }
  })

  it('reads the model from a directory whose name has Vietnamese letters', () => {
    const dir = mkdtempSync(join(tmpdir(), 'tess-Việt-'))
    try {
      const data = join(dir, 'dữ liệu')
      mkdirSync(data)
      copyFileSync(join(TESSDATA, 'vie.traineddata'), join(data, 'vie.traineddata'))
      const viaOddPath = createTesseractOcrEngine({
        nodePath: process.execPath,
        helperScript: HELPER,
        tessdataDir: data,
      })!
      const got = viaOddPath(png('en'), PAGE)
      expect(got).not.toBeNull()
      expect(cer(readingOrder(got!.lines), groundTruth('en'))).toBeLessThan(0.02)
    } finally {
      rmSync(dir, { recursive: true, force: true })
    }
  })
})

describe('the helper never touches the network', () => {
  it('treats a URL-looking model directory as a missing local directory (exit 4, no fetch)', () => {
    const res = spawnSync(process.execPath, [HELPER, 'https://cdn.example.com/tessdata', 'vie'], {
      input: png('en'),
      encoding: 'utf8',
    })
    expect(res.status).toBe(4)
    expect(res.stdout).toBe('')
    expect(res.stderr).toContain('language model not found')
    expect(
      createTesseractOcrEngine({
        nodePath: process.execPath,
        helperScript: HELPER,
        tessdataDir: 'https://cdn.example.com/tessdata',
      }),
    ).toBeNull()
  })

  it('pins the local langPath and the no-cache mode in the script', () => {
    const src = readFileSync(HELPER, 'utf8')
    expect(src).toContain("cacheMethod: 'none'")
    expect(src).toContain('langPath,')
    expect(src).not.toMatch(/https?:\/\//)
  })

  describe('under a preload that throws on every network API', () => {
    const PRELOAD = join(FIXTURES, 'no-network-preload.cjs')
    let dir: string
    beforeAll(() => {
      dir = mkdtempSync(join(tmpdir(), 'tess-net-'))
    })
    afterAll(() => rmSync(dir, { recursive: true, force: true }))

    const attempts = (file: string) => (existsSync(file) ? readFileSync(file, 'utf8').trim() : '')

    it('the preload trips in the main thread and, inherited through execArgv, in a worker thread', () => {
      const log = join(dir, 'sanity.txt')
      const script =
        "const { Worker } = require('node:worker_threads')\n" +
        "try { require('node:net').connect(1, '127.0.0.1') } catch {}\n" +
        'new Worker(\'try { fetch("http://127.0.0.1:1") } catch {}\', { eval: true })\n'
      const res = spawnSync(process.execPath, ['--require', PRELOAD, '-e', script], {
        env: { ...process.env, NET_ATTEMPTS_FILE: log },
        timeout: 30_000,
      })
      expect(res.status).toBe(0)
      expect(attempts(log).split('\n').sort()).toEqual(['fetch', 'net.connect'])
    })

    it('recognizes a page with exit 0 and zero network attempts', () => {
      const log = join(dir, 'helper.txt')
      const res = spawnSync(process.execPath, ['--require', PRELOAD, HELPER, TESSDATA, 'vie'], {
        input: png('vi'),
        maxBuffer: 64 << 20,
        env: { ...process.env, ELECTRON_RUN_AS_NODE: '1', NET_ATTEMPTS_FILE: log },
        timeout: 60_000,
      })
      expect(res.stderr.toString()).not.toContain('network attempt')
      expect(res.status).toBe(0)
      expect(res.stdout.toString('utf8')).toContain('Cộng hòa xã hội chủ nghĩa Việt Nam')
      expect(attempts(log)).toBe('')
    })
  })
})

describe('the helper process environment', () => {
  /** a parent environment that would run foreign code in, or reconfigure, a plain Node */
  function withHostileEnv<T>(run: () => T, dir: string): T {
    const evil = join(dir, 'evil-preload.cjs')
    writeFileSync(evil, "throw new Error('foreign code ran in the OCR helper')\n")
    const saved = { ...process.env }
    process.env.NODE_OPTIONS = `--require ${JSON.stringify(evil)}`
    process.env.NODE_PATH = join(dir, 'no-such-node-path')
    process.env.NODE_EXTRA_CA_CERTS = join(dir, 'no-such-ca.pem')
    try {
      return run()
    } finally {
      for (const k of ['NODE_OPTIONS', 'NODE_PATH', 'NODE_EXTRA_CA_CERTS']) {
        if (saved[k] === undefined) delete process.env[k]
        else process.env[k] = saved[k]
      }
    }
  }

  it('still recognizes under a parent NODE_OPTIONS=--require <throwing file>', () => {
    const dir = mkdtempSync(join(tmpdir(), 'tess-env-'))
    try {
      // the control: the same environment crashes a Node that inherits it
      const control = withHostileEnv(
        () => spawnSync(process.execPath, ['-e', '0'], { env: process.env, encoding: 'utf8' }),
        dir,
      )
      expect(control.status).not.toBe(0)
      expect(control.stderr).toContain('foreign code ran')
      const got = withHostileEnv(() => engine(png('en'), PAGE), dir)
      expect(got).not.toBeNull()
      expect(cer(readingOrder(got!.lines), groundTruth('en'))).toBeLessThan(0.02)
    } finally {
      rmSync(dir, { recursive: true, force: true })
    }
  })

  it('hands the helper none of NODE_OPTIONS / NODE_PATH / NODE_EXTRA_CA_CERTS, its own directory as cwd, and overwrites GENOFFICE_OCR_PARENT_PID (R2-1)', async () => {
    const dir = mkdtempSync(join(tmpdir(), 'tess-env-'))
    try {
      mkdirSync(join(dir, 'tessdata'))
      writeFileSync(join(dir, 'tessdata', 'vie.traineddata'), 'x')
      for (const pkg of ['tesseract.js', 'pngjs']) {
        mkdirSync(join(dir, 'node_modules', pkg), { recursive: true })
        writeFileSync(join(dir, 'node_modules', pkg, 'package.json'), `{"name":"${pkg}"}`)
      }
      writeFileSync(
        join(dir, 'tess-ocr.cjs'),
        'const e = process.env\n' +
          "const t = [process.cwd(), String(e.NODE_OPTIONS), String(e.NODE_PATH), String(e.NODE_EXTRA_CA_CERTS), e.ELECTRON_RUN_AS_NODE, e.PATH ? 'path' : 'nopath', String(e.GENOFFICE_OCR_PARENT_PID)].join('|')\n" +
          'process.stdout.write(JSON.stringify({ lines: [{ t, c: 0.9, b: [0, 0, 1, 1] }] }))\n',
      )
      const fake = createTesseractOcrEngine({
        nodePath: process.execPath,
        helperScript: join(dir, 'tess-ocr.cjs'),
        tessdataDir: join(dir, 'tessdata'),
      })!
      const fakeAsync = createTesseractOcrEngineAsync({
        nodePath: process.execPath,
        helperScript: join(dir, 'tess-ocr.cjs'),
        tessdataDir: join(dir, 'tessdata'),
      })!
      process.env.GENOFFICE_OCR_PARENT_PID = '777777'
      try {
        const got = withHostileEnv(() => fake(png('en'), PAGE), dir)
        const [cwd, nodeOptions, nodePath, caCerts, runAsNode, path, parentPid] =
          got!.lines[0]!.text.split('|')
        expect(realpathSync(cwd!)).toBe(realpathSync(dir))
        expect([nodeOptions, nodePath, caCerts]).toEqual(['undefined', 'undefined', 'undefined'])
        expect(runAsNode).toBe('1')
        expect(path).toBe('path') // everything else is inherited
        expect(parentPid).toBe(String(process.pid))

        const gotAsync = await fakeAsync(png('en'), PAGE)
        const asyncParts = gotAsync!.lines[0]!.text.split('|')
        expect(asyncParts[6]).toBe(String(process.pid))
      } finally {
        delete process.env.GENOFFICE_OCR_PARENT_PID
      }
    } finally {
      rmSync(dir, { recursive: true, force: true })
    }
  })

  it('exits non-zero immediately at startup before stdin/OCR work when GENOFFICE_OCR_PARENT_PID mismatches process.ppid (R2-1)', () => {
    const mismatchedPpid = process.pid === 1 ? 2 : 1
    const res = spawnSync(process.execPath, [HELPER, TESSDATA, 'vie'], {
      input: png('vi'),
      maxBuffer: 64 << 20,
      env: {
        ...process.env,
        ELECTRON_RUN_AS_NODE: '1',
        GENOFFICE_OCR_PARENT_PID: String(mismatchedPpid),
      },
    })
    expect(res.status).toBe(1)
    expect(res.stdout.length).toBe(0)
  })
})

describe('OCR chain with the real Tesseract engine', () => {
  const fake = () =>
    vi.fn<OcrEngine>(() => ({
      lines: [{ text: 'system', confidence: 1, box: { x0: 0, y0: 0, x1: 1, y1: 1 } }],
    }))
  const cached =
    (name: string): OcrEngine =>
    () =>
      recognitions[name]!

  it('keeps a Vietnamese page on Tesseract (the system engine is never asked)', () => {
    const fallback = fake()
    expect(chainOcrEngines(cached('vi'), fallback)(png('vi'), PAGE)).toBe(recognitions.vi)
    expect(fallback).not.toHaveBeenCalled()
  })

  it('keeps a French page on Tesseract (it reads accents better than en-US system OCR)', () => {
    const fallback = fake()
    expect(chainOcrEngines(cached('fr'), fallback)(png('fr'), PAGE)).toBe(recognitions.fr)
    expect(fallback).not.toHaveBeenCalled()
  })

  it('hands a Chinese page to the system engine', () => {
    const fallback = fake()
    const got = chainOcrEngines(cached('zh'), fallback)(png('zh'), PAGE)
    expect(fallback).toHaveBeenCalledTimes(1)
    expect(got?.lines[0]?.text).toBe('system')
  })

  it('hands an English page to the system engine, and keeps Tesseract when that has nothing', () => {
    const fallback = fake()
    expect(chainOcrEngines(cached('en'), fallback)(png('en'), PAGE)?.lines[0]?.text).toBe('system')
    expect(fallback).toHaveBeenCalledTimes(1)
    const none: OcrEngine = () => null
    expect(chainOcrEngines(cached('en'), none)(png('en'), PAGE)).toBe(recognitions.en)
  })

  it('returns null for the Chinese page when there is no system engine (Linux)', () => {
    expect(chainOcrEngines(cached('zh'), null)(png('zh'), PAGE)).toBeNull()
  })

  it('returns null for the Chinese page when the system engine has nothing (no zh recognizer)', () => {
    for (const nothing of [
      () => null,
      () => ({ lines: [] }),
      () => ({ lines: [{ text: ' ', confidence: 1, box: { x0: 0, y0: 0, x1: 1, y1: 1 } }] }),
    ]) {
      expect(chainOcrEngines(cached('zh'), nothing)(png('zh'), PAGE)).toBeNull()
    }
    const boom: OcrEngine = () => {
      throw new Error('helper failed')
    }
    expect(chainOcrEngines(cached('zh'), boom)(png('zh'), PAGE)).toBeNull()
  })

  it('the async chain decides the same on the real recognitions', async () => {
    const asyncOf = (name: string) => () => Promise.resolve(recognitions[name]!)
    const none = () => Promise.resolve(null)
    expect(await chainOcrEnginesAsync(asyncOf('zh'), none)(png('zh'), PAGE)).toBeNull()
    expect(await chainOcrEnginesAsync(asyncOf('zh'), null)(png('zh'), PAGE)).toBeNull()
    expect(await chainOcrEnginesAsync(asyncOf('vi'), none)(png('vi'), PAGE)).toBe(recognitions.vi)
    expect(await chainOcrEnginesAsync(asyncOf('en'), none)(png('en'), PAGE)).toBe(recognitions.en)
  })
})

/** a scanned page the way the pipeline hands it to tryOcrScannedPage */
function scannedPage(): ExtractedPage {
  return {
    index: 0,
    widthPt: 612,
    heightPt: 792,
    rotation: 0,
    chars: [],
    images: [],
    paths: [],
    degraded: false,
    scanned: true,
    hasStructTree: false,
    vectorRegions: [],
    badUnicodeRatio: 0,
    render: { data: new Uint8Array([1]), mime: 'image/png', pixelWidth: 612, pixelHeight: 792 },
  }
}

describe('a page the vie model cannot read keeps its scan bitmap (tryOcrScannedPage on the real zh recognition)', () => {
  const cached =
    (name: string): OcrEngine =>
    () =>
      recognitions[name]!
  const none: OcrEngine = () => null

  it('through the chain with a null system engine result', () => {
    expect(tryOcrScannedPage(scannedPage(), chainOcrEngines(cached('zh'), none))).toBeNull()
  })

  it('through the chain with no system engine at all (Linux)', () => {
    expect(tryOcrScannedPage(scannedPage(), chainOcrEngines(cached('zh'), null))).toBeNull()
  })

  it('the full conversion keeps the bitmap (status scanned) on both', async () => {
    const { PDFDocument } = await import('pdf-lib')
    const doc = await PDFDocument.create()
    const page = doc.addPage([(808 * 72) / 200, (538 * 72) / 200])
    const image = await doc.embedPng(png('zh'))
    page.drawImage(image, { x: 0, y: 0, width: page.getWidth(), height: page.getHeight() })
    const pdf = await doc.save()
    for (const fallback of [none, null]) {
      const result = await convertPdfToDocx(pdf, {
        pdfium: await loadPdfium(),
        renderScale: 2,
        ocr: chainOcrEngines(cached('zh'), fallback),
      })
      expect(result.pageResults[0]!.status).toBe('scanned')
      const parsed = await parseDocx(result.docx)
      expect(parsed.blocks.filter((b) => b.type === 'image')).toHaveLength(1)
    }
  }, 60_000)

  it('a mixed page (junk lines at c 0.5-0.6 plus Latin lines) would replace the bitmap unguarded and does not through the chain', () => {
    const at = (y: number) => ({ x0: 0.1, y0: y, x1: 0.6, y1: y + 0.03 })
    const mixed: OcrRecognition = {
      paperShare: 0.95,
      lines: [
        { text: '会议纪要项目管理委员会第三次会议', confidence: 0.5, box: at(0.9) },
        { text: '技术组报告了数据迁移的进度完成', confidence: 0.55, box: at(0.85) },
        { text: '财务部建议增加测试人员的预算', confidence: 0.6, box: at(0.8) },
        { text: '河内办公室第三会议室二〇二六年', confidence: 0.52, box: at(0.75) },
        { text: 'Hà Nội, ngày 15 tháng 9 năm 2026', confidence: 0.95, box: at(0.7) },
        { text: 'Phòng họp số 3 tầng 5', confidence: 0.9, box: at(0.65) },
      ],
    }
    const raw: OcrEngine = () => mixed
    // the hazard the review found: the page-level gates in ocr.ts pass this page
    expect(tryOcrScannedPage(scannedPage(), raw)).not.toBeNull()
    expect(ocrFallbackReason(mixed)).not.toBeNull()
    expect(tryOcrScannedPage(scannedPage(), chainOcrEngines(raw, none))).toBeNull()
    expect(tryOcrScannedPage(scannedPage(), chainOcrEngines(raw, null))).toBeNull()
  })
})

describe('resolveLocalOcrEngine', () => {
  let root: string
  beforeAll(() => {
    root = mkdtempSync(join(tmpdir(), 'tess-res-'))
  })
  afterAll(() => rmSync(root, { recursive: true, force: true }))

  it('resolves the repo copy in dev', () => {
    expect(resolveLocalOcrEngine({ devPackageDir: PKG })).toBeTypeOf('function')
  })

  it('returns null where nothing is installed', () => {
    expect(resolveLocalOcrEngine({ resourcesPath: root })).toBeNull()
  })

  it('prefers the packaged Resources/ocr/tesseract layout and runs it with ELECTRON_RUN_AS_NODE', () => {
    const res = join(root, 'Resources')
    const tess = join(res, 'ocr', 'tesseract')
    mkdirSync(join(tess, 'tessdata'), { recursive: true })
    for (const pkg of ['tesseract.js', 'pngjs']) {
      mkdirSync(join(tess, 'node_modules', pkg), { recursive: true })
      writeFileSync(
        join(tess, 'node_modules', pkg, 'package.json'),
        `{"name":"${pkg}","version":"0.0.0"}`,
      )
    }
    writeFileSync(join(tess, 'tessdata', 'vie.traineddata'), 'x')
    // a stand-in helper: proves which script ran, with which args and env
    writeFileSync(
      join(tess, 'tess-ocr.cjs'),
      "const path = require('path')\n" +
        "const t = ['packaged', process.env.ELECTRON_RUN_AS_NODE, path.basename(process.argv[2]), process.argv[3]].join(' ')\n" +
        'process.stdout.write(JSON.stringify({ paper: 0.5, lines: [{ t, c: 0.9, b: [0.1, 0.2, 0.3, 0.4] }] }))\n',
    )
    const engine = resolveLocalOcrEngine({ resourcesPath: res, devPackageDir: PKG })!
    const got = engine(png('en'), PAGE)
    expect(got?.paperShare).toBe(0.5)
    expect(got?.lines[0]?.text).toBe('packaged 1 tessdata vie')
    expect(got?.lines[0]?.box).toEqual({ x0: 0.1, y0: 0.2, x1: 0.3, y1: 0.4 })
  })
})

describe('scanned Vietnamese PDF through the local engine chain', () => {
  it('converts the scan to editable Vietnamese text in the docx', async () => {
    const { PDFDocument } = await import('pdf-lib')
    const doc = await PDFDocument.create()
    // page sized from the 200 dpi scan so the render keeps the scan's aspect ratio
    const page = doc.addPage([(1214 * 72) / 200, (712 * 72) / 200])
    const image = await doc.embedPng(png('vi'))
    page.drawImage(image, { x: 0, y: 0, width: page.getWidth(), height: page.getHeight() })
    const engine = resolveLocalOcrEngine({ devPackageDir: PKG })!
    const result = await convertPdfToDocx(await doc.save(), {
      pdfium: await loadPdfium(),
      renderScale: 2,
      ocr: engine,
    })
    expect(result.pageResults[0]!.status).toBe('ocr')
    const parsed = await parseDocx(result.docx)
    const text = JSON.stringify(parsed.blocks)
    for (const phrase of ['Cộng hòa xã hội', 'Độc lập', 'kỹ sư trưởng', 'Đà Nẵng']) {
      expect(text, phrase).toContain(phrase)
    }
    expect(parsed.blocks.filter((b) => b.type === 'image')).toHaveLength(0)
  }, 60_000)
})
